p.extended-example:
Generic pattern used throughout this chapter for walking an
object-record stream.



objhdr * obj = (objhdr*)(base + start_offset);

while (1)

{

  int len = obj->len0 + (obj->len1 << 8);

  if (len == 0) break;              /* end of stream */

  void * body = (char*)obj + sizeof(objhdr);

  /* interpret *body* according to obj->type */

  obj = (objhdr*)((char*)obj + len);   /* len already includes the header */

}

Locating and iterating over a document's colour table.



icolourstr * col = (icolourstr*)(docdata + docdata->colour1);

int ncol = (docdata->tints - docdata->colour1) / sizeof(icolourstr);

int n;

for (n = 0; n < ncol; n++, col++)

{

  if (*col->name == 0) continue;      /* unused slot */

  if (col->flags & 0x2)

  {

    /* tint entry: base colour index, tint amount in col->k */

  }

  else

  {

    /* base colour: model selected by (col->y & 0x3) */

  }

}

Locating a dictionary entry's data in a single-file document.



int * mdict = (int*)(docdata + docdata->mdict1);

int offset = mdict[dcindex];

int length = mdict[dcindex + 1] - mdict[dcindex];

fseek(inputfp, offset, SEEK_SET);

/* read *length* bytes: an ilinestr-framed sequence for a

  DCTEXT entry, or raw picture data for a DCPICT entry */
